import React,{useState} from 'react';
import {useResource} from './state.js';
import {ResourceState} from './ui.jsx';
import {Modal} from './preferences.tsx';
import {useWritingRequest} from './writing-request.js';
const types={link:'人物与资料',event:'章节事件',foreshadow:'伏笔'};
const links={appearance:'实际出场',mention:'仅被提及',reference:'资料关联'};
const statuses={planned:'计划',planted:'已埋设',developing:'推进中',recovered:'已回收',abandoned:'已放弃'};
const evidenceTypes={plant:'埋设',progress:'推进',recover:'回收'};
const stateLabels={pending:'待确认',applied:'已采用',dismissed:'已忽略'};
export function ReviewInbox({call,novelId,chapter,busy,run,dirty=false}){
 const write=useWritingRequest(call),[tick,setTick]=useState(0),[id,setId]=useState(null),[selected,setSelected]=useState([]),[error,setError]=useState(''),[message,setMessage]=useState('');
 const resource=useResource(()=>Promise.all([call('writing.review.list',{novelId,chapterId:chapter.id}),call('graph.list',{novelId}),call('writing.foreshadow.list',{novelId})]),[call,novelId,chapter.id,tick]);
 const detail=useResource(()=>id?call('writing.review.get',{novelId,id}):Promise.resolve(null),[call,novelId,id,tick]);
 const nodes=resource.value?.[1]||[],shadows=resource.value?.[2]||[],name=nodeId=>{const node=nodes.find(n=>n.id===nodeId);if(!node)return '资料已删除';return node.name+(nodes.filter(n=>n.name===node.name).length>1?` · ${nodeId.slice(0,8)}`:'');};
 const refresh=()=>{setTick(n=>n+1);setSelected([]);};
 const process=action=>run(async()=>{setError('');setMessage('');try{const result=await write(action,{novelId,id,expectedRevision:detail.value.revision,itemIds:selected,confirmed:true,reason:action.endsWith('apply')?'作者在整理预览中确认所选候选':'作者忽略所选候选'});setMessage(action.endsWith('apply')?`已采用 ${selected.length} 项，未选建议仍待确认。`:`已忽略 ${selected.length} 项。`);refresh();return result;}catch(e){setError(e.message);}});
 const match=()=>run(async()=>{setError('');setMessage('');try{const hits=await call('writing.link.candidates',{novelId,chapterId:chapter.id});if(!hits.items.length){setMessage('没有匹配到已建立的资料。');return;}const args={novelId,chapterId:chapter.id,expectedChapterRevision:hits.chapterRevision,title:'姓名与别名匹配候选',items:hits.items.slice(0,30).map(c=>({id:c.nodeId,kind:'link',nodeId:c.nodeId,linkKind:c.type==='character_card'?'mention':'reference',evidence:c.evidence,reason:`正文匹配“${c.matched}”；尚未判断实际出场。`}))},preview=await call('writing.review.preview',args),saved=await write('writing.review.submit',{...args,proof:preview.proof});setId(saved.id);refresh();setMessage('候选已放入清单，尚未写入正式资料。');}catch(e){setError(e.message);}});
 return <section className="review-inbox" aria-label="整理建议清单"><p className="muted">AI 整理的候选先保留在这里。核对正文依据，勾选后采用；未选内容不会成为事实。无需额外配置模型。</p>{dirty&&<p className="notice">正文草稿尚未保存，请先返回正文保存再采用建议。</p>}<div className="row"><button disabled={busy} onClick={refresh}>刷新建议</button><button disabled={busy||dirty} onClick={match}>从姓名匹配建立候选</button></div>{error&&<p className="notice error" role="alert">{error}</p>}{message&&<p role="status">{message}</p>}
 <ResourceState resource={resource}>{resource.value&&<>{!id?<div className="review-batches">{resource.value[0].length?resource.value[0].map(r=><button className="review-batch" key={r.id} onClick={()=>{setId(r.id);setSelected([]);setError('');setMessage('');}}><strong>{r.title}</strong><small>正文版本 {r.chapterRevision} · {r.pending?r.pending+' 项待确认':'已处理'} / {r.total} 项{r.stale?' · 需重新核对':''}</small><span aria-hidden="true">›</span></button>):<div className="review-empty"><h3>还没有整理建议</h3><p>可在聊天中让 AI 整理本章事件、人物出场和伏笔，并提交候选到工作台。也可先建立姓名匹配候选。</p></div>}</div>:<><button onClick={()=>{setId(null);setSelected([]);}}>‹ 返回建议清单</button><ResourceState resource={detail}>{detail.value&&(()=>{const r=detail.value,pending=r.items.filter(i=>i.state==='pending'),valid=pending.filter(i=>!i.stale);return <><h3>{r.title}</h3><p className="muted">{r.chapterTitle} · 来源版本 {r.chapterRevision} · {r.actor?.kind==='agent'?'AI 提交':'作者建立'}</p><div className="row"><button disabled={busy||!pending.length} onClick={()=>setSelected(valid.map(i=>i.id))}>选择可采用项</button><button disabled={busy||!selected.length} onClick={()=>setSelected([])}>取消选择</button></div><div className="review-items">{r.items.map(i=><article className={`review-item review-${i.kind}`} key={i.id}><header><label><input type="checkbox" aria-label={`选择建议 ${i.id}`} checked={selected.includes(i.id)} disabled={busy||i.state!=='pending'} onChange={e=>setSelected(old=>e.target.checked?[...old,i.id]:old.filter(id=>id!==i.id))}/><span>{types[i.kind]}</span></label><small>{stateLabels[i.state]}</small></header>{i.kind==='link'?<><h4>{name(i.nodeId)}</h4><p>{links[i.linkKind]}</p><blockquote>{i.evidence}</blockquote></>:i.kind==='event'?<><h4>{i.value.title}</h4><p>{i.value.storyTime||i.value.storyDate||'故事时间未注明'} · {i.value.planned?'计划事件':'正文事件'}</p><p className="review-content">{i.value.content}</p>{i.value.memoryRefs?.length>0&&<p>参与资料：{i.value.memoryRefs.map(name).join('、')}（不等于正式出场）</p>}<blockquote>{i.evidence}</blockquote></>:<><h4>{i.value.title||shadows.find(f=>f.id===i.targetId)?.title||'伏笔'}</h4><p>{i.targetId?'更新已有伏笔':'新建伏笔'} · {i.beforeStatus?statuses[i.beforeStatus]+' → ':''}{statuses[i.value.status]||'保留现有状态'}</p><p className="review-content">{i.value.content}</p>{i.value.evidence?.map((e,index)=><blockquote key={index}><small>{evidenceTypes[e.kind]} · 正文版本 {e.revision}</small><br/>{e.evidence}</blockquote>)}</>}{i.reason&&<p className="muted">整理理由：{i.reason}</p>}{i.stale&&<p className="notice">正文或关联资料已变动。此项需要重新整理，不能直接采用。</p>}</article>)}</div>{pending.length>0&&<footer className="review-actions"><small>已选 {selected.length} 项</small><button disabled={busy||!selected.length} onClick={()=>process('writing.review.dismiss')}>忽略所选</button><button className="primary" disabled={busy||dirty||!selected.length||r.items.some(i=>selected.includes(i.id)&&i.stale)} onClick={()=>process('writing.review.apply')}>确认采用所选</button></footer>}</>;})()}</ResourceState></>}</>}</ResourceState></section>;
}
export function ReviewDialog(props){return <Modal title="本章整理建议" close={props.close} className="review-modal"><ReviewInbox {...props}/></Modal>;}
export const reviewStyles=`
.cuigengji .review-inbox{min-width:0}.cuigengji .review-batches,.cuigengji .review-items{display:grid;gap:12px;margin:16px 0}.cuigengji .review-batch{display:grid;grid-template-columns:1fr auto;text-align:left;gap:6px;padding:16px;min-width:0}.cuigengji .review-batch strong,.cuigengji .review-batch small{overflow-wrap:anywhere}.cuigengji .review-batch small{grid-column:1;opacity:.7}.cuigengji .review-batch>span{grid-column:2;grid-row:1/3;align-self:center}.cuigengji .review-empty{padding:20px 6px}.cuigengji .review-item{border:1px solid var(--dsw-alias-border-l1,#dde0e6);border-left:4px solid var(--dsw-alias-state-business-primary,#4d6bfe);border-radius:12px;padding:12px 16px;min-width:0;overflow-wrap:anywhere}.cuigengji .review-link{border-left-color:#8872d7}.cuigengji .review-foreshadow{border-left-color:#bc9257}.cuigengji .review-item header{display:flex;align-items:center;justify-content:space-between;gap:8px}.cuigengji .review-item header label{display:flex;align-items:center;gap:8px;margin:0}.cuigengji .review-item h4{font-size:16px;margin:12px 0 6px}.cuigengji .review-item blockquote{margin:8px 0;padding:8px 12px;border-left:2px solid var(--dsw-alias-border-l1,#dde0e6);white-space:pre-wrap;font-size:13px}.cuigengji .review-content{white-space:pre-wrap}.cuigengji .review-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:flex-end;padding:16px 0}.cuigengji .review-modal{width:min(760px,calc(100vw - 32px))}@media(max-width:600px){.cuigengji .review-modal{width:100%;max-width:100%;height:100%;max-height:100%;margin:0;border:0;border-radius:0}.cuigengji .review-modal .utility-content{padding:12px}.cuigengji .review-item{padding:12px}.cuigengji .review-actions button{flex:1}}
`;
